/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field qtyBecomesNegative.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableQtyBecomesNegative extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, qtyBecomesNegative);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Enum);
    RetailInventTable retailInventTable;
    while select qtyBecomesNegative from retailInventTable
        group by qtyBecomesNegative
    {
        ret.add(retailInventTable.qtyBecomesNegative);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, qtyBecomesNegative));
    qbr.value(queryValue(_value));
}
